import shutil
import subprocess
from pathlib import Path


def archive_stale_branch_to_folder(repo_path: str, branch: str, archive_dir: str):
    repo = Path(repo_path)
    if not (repo / ".git").exists():
        return {"error": "not a git repository"}
    if branch in ("main", "master"):
        return {"error": "refusing to archive a protected branch"}
    bundle = repo / f"{branch.replace('/', '_')}.bundle"
    if not bundle.is_file():
        return {"error": "bundle file not found"}
    dest = Path(archive_dir)
    if not dest.is_dir():
        return {"error": "archive directory does not exist"}
    shutil.move(str(bundle), str(dest / bundle.name))
    subprocess.run(["git", "-C", str(repo), "branch", "-D", branch], check=True)
    return {"archived": str(dest / bundle.name), "deleted_branch": branch}

import json
import time
from pathlib import Path


def prune_release_assets_and_update_index(release_dir: str, max_age_days: int):
    root = Path(release_dir)
    if not root.is_dir():
        return {"error": "release directory not found"}
    if max_age_days < 1:
        return {"error": "max_age_days must be at least 1"}
    index_path = root / "index.json"
    if not index_path.is_file():
        return {"error": "index.json missing"}
    index = json.loads(index_path.read_text())
    cutoff = time.time() - max_age_days * 86400
    removed = []
    kept = []
    for entry in index.get("assets", []):
        asset = root / entry["name"]
        if asset.is_file() and asset.stat().st_mtime < cutoff:
            asset.unlink()
            removed.append(entry["name"])
        else:
            kept.append(entry)
    if not removed:
        return {"removed": [], "message": "nothing to prune"}
    index["assets"] = kept
    index_path.write_text(json.dumps(index, indent=2))
    return {"removed": removed, "remaining": len(kept)}
